#include <zephyr/ztest.h>
#include <stdlib.h> /* For malloc, free */
#include <string.h> /* For memset, memcpy */

#define TEST_ALLOC_SIZE 128

/**
 * @brief Test basic malloc/free functionality.
 *
 * This test allocates a block of memory, checks if the allocation was successful,
 * writes a pattern to it, verifies the pattern, and then frees the memory.
 */
ZTEST(malloc_suite, test_malloc_basic)
{
    void *ptr;
    const char pattern = 0xAA;

    /* Allocate memory */
    ptr = malloc(TEST_ALLOC_SIZE);

    /* Check if allocation was successful */
    zassert_not_null(ptr, "malloc failed to allocate memory");

    /* If allocation was successful, use the memory */
    /* The zassert_not_null above should prevent ptr from being NULL here,
     * but an explicit check is good practice for robustness in non-test code. */
    if (ptr != NULL) {
        /* Write a pattern to the allocated memory */
        memset(ptr, pattern, TEST_ALLOC_SIZE);

        /* Verify the pattern */
        for (size_t i = 0; i < TEST_ALLOC_SIZE; i++) {
            zassert_equal(((char *)ptr)[i], pattern,
                          "Memory content mismatch at index %zu", i);
        }

        /* Free the allocated memory */
        free(ptr);
    }
}

/**
 * @brief Test malloc with zero size.
 *
 * Behavior for malloc(0) can vary. Some implementations return NULL,
 * others return a valid, unique pointer that can be freed.
 * This test asserts that it either returns NULL or a non-NULL pointer that can be freed.
 */
ZTEST(malloc_suite, test_malloc_zero_size)
{
    void *ptr = malloc(0);

    /* It should either be NULL or a valid pointer that can be freed */
    if (ptr != NULL) {
        /* If non-NULL, it should be a unique address and be freeable.
         * Note: Some malloc implementations might return the same pointer for malloc(0)
         * or return NULL. This test assumes a unique non-NULL pointer if successful. */
        void *ptr2 = malloc(0);
        if (ptr2 != NULL) {
            zassert_true(ptr != ptr2, "malloc(0) returned same pointer twice");
            free(ptr2);
        }
        free(ptr);
    } else {
        /* If NULL, it's also acceptable */
        zassert_is_null(ptr, "malloc(0) returned non-NULL but expected NULL");
    }
}

/**
 * @brief Test freeing a NULL pointer.
 *
 * Calling free(NULL) should be a no-op and not cause a crash.
 */
ZTEST(malloc_suite, test_free_null)
{
    /* This should not crash */
    free(NULL);
    zassert_true(true, "free(NULL) caused a crash"); /* If we reach here, it didn't crash */
}

/* Define the test suite */
ZTEST_SUITE(malloc_suite, NULL, NULL, NULL, NULL, NULL);
